// Convert input polygons to CGAL polygons
internal::Polygon_2 cgalP1, cgalP2;
for (const auto& point : P1.outer()) {
    cgalP1.push_back(internal::Point_2(point.x(), point.y()));
}
for (const auto& point : P2.outer()) {
    cgalP2.push_back(internal::Point_2(point.x(), point.y()));
}

// Perform boolean difference operation
internal::Pwh_list_2 difference_result;
CGAL::difference(cgalP1, cgalP2, std::back_inserter(difference_result));

// Convert CGAL result back to our format
std::vector<PolygonWithHoles2d> result;
for (const auto& pwh : difference_result) {
    PolygonWithHoles2d polyWithHoles;

    // Convert outer boundary
    Polygon2d outer;
    for (const auto& point : pwh.outer_boundary()) {
        double x, y;
        internal::getCoordinates(point, x, y);
        outer.push_back(Point2d(x, y));
    }
    polyWithHoles.setOuterBoundary(outer);

    // Convert holes
    for (auto hole_it = pwh.holes_begin(); hole_it != pwh.holes_end(); ++hole_it) {
        Polygon2d hole;
        for (const auto& point : *hole_it) {
            double x, y;
            internal::getCoordinates(point, x, y);
            hole.push_back(Point2d(x, y));
        }
        polyWithHoles.addHole(hole);
    }

    result.push_back(polyWithHoles);
}

return result;

